solution.python:
def rob(nums):
    take, skip = 0, 0
    for x in nums: take, skip = skip + x, max(take, skip)
    return max(take, skip)

solution.cpp:
long long rob(vector<int>& a) {
    long long take = 0, skip = 0;
    for (int x : a) { long long t = skip + x; skip = max(take, skip); take = t; }
    return max(take, skip);
}
